package com.game_manager.gm.workflow; import java.util.List; public record WorkflowSchema(String initialStep,List<Step> steps,List<Transition> transitions){public record Step(String key,String label,String role,int dueHours,int reminderHours,String escalationRole){}public record Transition(String from,String action,String target,boolean reasonRequired){}public Step step(String key){return steps.stream().filter(s->s.key().equals(key)).findFirst().orElseThrow();}public Transition transition(String from,String action){return transitions.stream().filter(t->t.from().equals(from)&&t.action().equals(action)).findFirst().orElse(null);}}
